def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            typ, _ = peek()
            if typ == '+':
                advance()
                val = val + parse_term()
            elif typ == '-':
                advance()
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            typ, _ = peek()
            if typ == '*':
                advance()
                val = val * parse_factor()
            elif typ == '/':
                advance()
                rhs = parse_factor()
                # truncate toward zero
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                val = q
            else:
                break
        return val

    def parse_factor():
        typ, _ = peek()
        if typ == '-':
            advance()
            return -parse_factor()
        if typ == '+':
            advance()
            return parse_factor()
        return parse_atom()

    def parse_atom():
        typ, val = advance()
        if typ == 'NUM':
            return val
        if typ == '(':
            v = parse_expr()
            typ2, _ = advance()
            if typ2 != ')':
                raise ValueError("Expected ')'")
            return v
        raise ValueError(f"Unexpected token: {typ}")

    result = parse_expr()
    return result

